def _pv_parts(n, allowed, distinct):
    ways = [1] + [0] * n
    for p in allowed:
        if distinct:
            for s in range(n, p - 1, -1):
                ways[s] += ways[s - p]
        else:
            for s in range(p, n + 1):
                ways[s] += ways[s - p]
    return ways[n]

